class Oracle(unittest.TestCase):
    """Exhaustive round trip against datetime.isocalendar for 1600-2400 (test-only use of datetime)."""

    def test_iso_week_matches_datetime(self):
        d = datetime.date(1600, 1, 1)
        end = datetime.date(2400, 12, 31)
        while d <= end:
            y, w, wd = d.isocalendar()
            got = iso_week(d.year, d.month, d.day)
            if got != (y, w, wd):
                self.fail(f"{d}: got {got}, want {(y, w, wd)}")
            d += datetime.timedelta(days=1)

    def test_from_iso_matches_datetime_and_inverts(self):
        d = datetime.date(1600, 1, 1)
        end = datetime.date(2400, 12, 31)
        while d <= end:
            y, w, wd = d.isocalendar()
            if from_iso(y, w, wd) != (d.year, d.month, d.day):
                self.fail(f"from_iso{(y, w, wd)} != {d}")
            d += datetime.timedelta(days=1)

    def test_from_iso_rejects_every_missing_week(self):
